const text = String($json.text || '').trim();
let intent = 'chat';
if (/gasto|despesa|paguei|comprei|conta|pagar|lan[cç]ar|r\$|\d+[.,]\d{2}/i.test(text)) intent = 'finance';
else if (/c[oó]digo|gera(r)?\s*c[oó]digo|ativa[cç][aã]o|king[-_\s]?[a-z0-9]/i.test(text)) intent = 'code';
else if (/sentry|erro|bug|diagn[oó]stico|health|caiu|status|site/i.test(text)) intent = 'diag';

let amount = null;
const am = text.match(/r\$\s*(\d+[.,]?\d*)/i) || text.match(/(\d+[.,]\d{2})/) || text.match(/\b(\d{1,6})\b/);
if (am) amount = parseFloat(String(am[1]).replace(',', '.'));

let type = 'EXPENSE';
if (/receita|recebi|entrou|ganhei/i.test(text)) type = 'INCOME';
let status = 'PENDING';
if (/paguei|pago|já\s*paguei|ja\s*paguei/i.test(text)) status = 'PAID';

let description = text.replace(/r\$\s*\d+[.,]?\d*/ig, '').replace(/\s+/g, ' ').trim().slice(0, 180) || 'Lançamento via Telegram';

let customCode = '';
const cm = text.match(/\b(KING[-_\s]?[A-Z0-9]+)\b/i) || text.match(/c[oó]digo[^A-Za-z0-9]*([A-Z0-9][-_A-Z0-9]{2,})/i);
if (cm) customCode = String(cm[1]).replace(/\s+/g, '').toUpperCase().slice(0, 32);

const today = new Date().toISOString().slice(0, 10);
return [{ json: { ...$json, intent, amount, type, status, description, customCode, transactionDate: today } }];

const prev = $input.first().json;
const base = String($env.CK_BASE_URL || 'https://www.conectaking.com.br').replace(/\/$/, '');
const token = String($env.CK_AGENT_JWT || '').trim();
const intent = prev.intent;

async function http(method, path, body) {
  const opts = {
    method,
    url: base + path,
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/json',
      ...(token ? { Authorization: 'Bearer ' + token } : {}),
    },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  };
  if (body !== undefined) opts.body = body;
  return this.helpers.httpRequest.call(this, opts);
}

let msg = '';
try {
  if (intent === 'diag') {
    const h = await http.call(this, 'GET', '/health');
    msg = 'Diagnóstico Conecta King\nHTTP ' + h.statusCode + '\n' + JSON.stringify(h.body).slice(0, 400);
  } else if (intent === 'finance') {
    if (!token) {
      msg = 'CK_AGENT_JWT não configurado no n8n. Peça ao Cursor para gerar o token.';
    } else if (!prev.amount || !(prev.amount > 0)) {
      msg = 'Não entendi o valor. Ex.: "lançar despesa R$ 100 contas para pagar"';
    } else {
      const body = {
        type: prev.type || 'EXPENSE',
        amount: Number(prev.amount),
        description: prev.description || 'Lançamento via Telegram',
        transaction_date: prev.transactionDate,
        status: prev.status || 'PENDING',
      };
      const r = await http.call(this, 'POST', '/api/finance/transactions', body);
      if (r.statusCode >= 200 && r.statusCode < 300) {
        const row = (r.body && r.body.data) || {};
        msg = 'Lançamento criado na Gestão Financeira.\n' +
          (body.type === 'INCOME' ? 'Receita' : 'Despesa') + ': R$ ' + body.amount.toFixed(2) +
          '\nStatus: ' + body.status +
          '\nDesc: ' + body.description +
          (row.id ? '\nID: ' + row.id : '');
      } else {
        msg = 'Falha ao lançar (' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300);
      }
    }
  } else if (intent === 'code') {
    if (!token) {
      msg = 'CK_AGENT_JWT não configurado no n8n.';
    } else if (!prev.customCode) {
      msg = 'Informe o código. Ex.: "gerar código KING-TESTTELE"';
    } else {
      const r = await http.call(this, 'POST', '/api/admin/codes/generate-manual', {
        customCode: prev.customCode,
        expiresAt: null,
      });
      if (r.statusCode >= 200 && r.statusCode < 300) {
        msg = 'Código criado: ' + prev.customCode;
      } else {
        msg = 'Falha ao criar código (' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300);
      }
    }
  } else {
    msg = 'Assistente Executivo (Telegram) online.\nComandos:\n• status / diagnóstico\n• lançar despesa R$ 100 ...\n• gerar código KING-XXXX';
  }
} catch (e) {
  msg = 'Erro ao executar: ' + String(e.message || e).slice(0, 300);
}

return [{ json: { ...prev, outMessage: msg } }];

const text = String($json.text || '').trim();
const name = $json.firstName || 'olá';
let msg = `Olá, ${name}! Sou o Assistente do Conecta King.\n\nPosso ajudar com acesso, planos e dúvidas.\nSite: https://www.conectaking.com.br\n\nPara atendimento humano, diga: falar com o King.`;
if (/senha|login|acesso/i.test(text)) msg = 'Acesse: https://www.conectaking.com.br/login — use e-mail e senha do cadastro. Esqueceu? Use "Esqueci minha senha" na tela de login.';
if (/plano|pre[cç]o|valor/i.test(text)) msg = 'Planos: https://www.conectaking.com.br — código de ativação o King libera no ADM.';
if (/humano|king|pessoa/i.test(text)) msg = 'Certo! Vou avisar o time. Em breve alguém retorna.';
return [{ json: { ...$json, outMessage: msg, escalate: /humano|king|pessoa/i.test(text) } }];
